#define RAYON_CORPS vec3(0.38, 0.52, 1.15)
#define RAYON_VENTRE vec3(0.32, 0.42, 0.75)
#define RAYON_NAGEOIRE_QUEUE vec3(0.04, 0.65, 0.55)
#define RAYON_NAGEOIRE_DORSALE vec3(0.035, 0.45, 0.6)
#define RAYON_NAGEOIRE_PECTORALE vec3(0.35, 0.025, 0.25)
#define POSITION_OEIL vec3(0.26, 0.18, 0.72)

#define CALCULER_QUADRIQUE(position, rayons) (length(position / rayons) * (length(position / rayons) - 1.0) / length(position / (rayons * rayons)))
#define CREER_MATRICE_ROTATION_2D(angle) mat2(cos(angle), -sin(angle), sin(angle), cos(angle))

float calculerCarteDistanceGeometrie(vec3 positionEspace, float tempsAnimation, float ondulationOndoiement, out float distanceCorps, out float distanceNageoires, out float distanceYeux) {
    vec3 positionCorpsBase = positionEspace - vec3(0.0, 0.0, 0.1);
    vec3 positionVentre = positionEspace - vec3(0.0, -0.15, 0.3);
    distanceCorps = min(CALCULER_QUADRIQUE(positionCorpsBase, RAYON_CORPS), CALCULER_QUADRIQUE(positionVentre, RAYON_VENTRE));

    vec3 positionNageoireQueue = positionEspace - vec3(0.0, 0.0, -1.15);
    positionNageoireQueue.yz *= CREER_MATRICE_ROTATION_2D(0.2);
    float distanceQueue = CALCULER_QUADRIQUE(positionNageoireQueue, RAYON_NAGEOIRE_QUEUE);

    vec3 positionNageoireDorsale = positionEspace - vec3(0.0, 0.55, -0.1);
    positionNageoireDorsale.yz *= CREER_MATRICE_ROTATION_2D(-0.4);
    float distanceDorsale = CALCULER_QUADRIQUE(positionNageoireDorsale, RAYON_NAGEOIRE_DORSALE);

    vec3 positionPectoraleDroite = positionEspace - vec3(0.38, -0.2, 0.35);
    positionPectoraleDroite.xy *= CREER_MATRICE_ROTATION_2D(-0.6 + ondulationOndoiement * 0.3);
    positionPectoraleDroite.yz *= CREER_MATRICE_ROTATION_2D(0.5);
    float distancePectoraleDroite = CALCULER_QUADRIQUE(positionPectoraleDroite, RAYON_NAGEOIRE_PECTORALE);

    vec3 positionPectoraleGauche = positionEspace - vec3(-0.38, -0.2, 0.35);
    positionPectoraleGauche.xy *= CREER_MATRICE_ROTATION_2D(0.6 - ondulationOndoiement * 0.3);
    positionPectoraleGauche.yz *= CREER_MATRICE_ROTATION_2D(0.5);
    float distancePectoraleGauche = CALCULER_QUADRIQUE(positionPectoraleGauche, RAYON_NAGEOIRE_PECTORALE);

    distanceNageoires = min(distanceQueue, min(distanceDorsale, min(distancePectoraleDroite, distancePectoraleGauche)));

    vec3 positionOeilGauche = positionEspace - vec3(-POSITION_OEIL.x, POSITION_OEIL.y, POSITION_OEIL.z);
    distanceYeux = min(length(positionEspace - POSITION_OEIL), length(positionOeilGauche)) - 0.095;

    return min(distanceYeux, min(distanceCorps, distanceNageoires));
}

vec3 appliquerDeformationOndulation(vec3 positionPoint, float tempsAnimation, float ondulationOndoiement) {
    positionPoint.y += sin(tempsAnimation * 0.5) * 0.1;
    positionPoint.xz *= CREER_MATRICE_ROTATION_2D(sin(tempsAnimation * 0.3) * 0.15);
    positionPoint.x -= ondulationOndoiement * 0.12 * smoothstep(0.5, -1.5, positionPoint.z);
    return positionPoint;
}

void mainImage(out vec4 couleurFragment, in vec2 coordonneeFragment) {
    vec2 resolutionEcran = iResolution.xy;
    vec2 coordonneesUV = (coordonneeFragment - 0.5 * resolutionEcran) / resolutionEcran.y;

    float tempsActuel = iTime;
    float angleCamera = tempsActuel * 0.25;

    vec3 positionOrigineRayon = vec3(sin(angleCamera) * 3.2, 0.4 + sin(tempsActuel * 0.5) * 0.2, cos(angleCamera) * 3.2);
    vec3 orientationVisee = normalize(vec3(0.0, -0.05, 0.0) - positionOrigineRayon);
    vec3 axeAxeHorizontal = normalize(cross(orientationVisee, vec3(0.0, 1.0, 0.0)));
    vec3 directionRayon = normalize(coordonneesUV.x * axeAxeHorizontal + coordonneesUV.y * cross(axeAxeHorizontal, orientationVisee) + 1.8 * orientationVisee);

    vec3 directionLumierePrincipale = normalize(vec3(0.8, 1.2, 0.6));
    vec3 couleurLumierePrincipale = vec3(1.0, 0.92, 0.8) * 3.5;

    vec3 directionLumiereRemplissage = normalize(vec3(-0.8, -0.2, -0.5));
    vec3 couleurLumiereRemplissage = vec3(0.1, 0.35, 0.6) * 1.5;

    vec3 directionLumiereRaseante = normalize(vec3(0.0, 0.5, -1.0));
    vec3 couleurLumiereRaseante = vec3(0.2, 0.6, 0.9) * 4.0;

    vec3 couleurArrierePlan = mix(vec3(0.01, 0.04, 0.09), vec3(0.002, 0.01, 0.03), length(coordonneesUV) * 0.8);
    vec3 couleurFinale = couleurArrierePlan;
    vec3 couleurDiffusionVolumetrique = vec3(0.0);

    float distanceParcourueTotal = 0.0;
    float densiteAccumulee = 0.0;
    float tempsAnimationPoisson = tempsActuel * 2.8;

    for (int etapeRaymarching = 0; etapeRaymarching < 96; etapeRaymarching++) {
        vec3 positionCouranteRayon = positionOrigineRayon + directionRayon * distanceParcourueTotal;
        float ondulationSegment = sin(tempsAnimationPoisson - positionCouranteRayon.z * 2.2);
        vec3 positionDeformee = appliquerDeformationOndulation(positionCouranteRayon, tempsAnimationPoisson, ondulationSegment);

        float distanceCorps, distanceNageoires, distanceYeux;
        float distanceEstimationSurface = calculerCarteDistanceGeometrie(positionDeformee, tempsAnimationPoisson, sin(tempsAnimationPoisson - positionDeformee.z * 2.2), distanceCorps, distanceNageoires, distanceYeux);

        float motifRayures = smoothstep(0.35, 0.65, sin(positionDeformee.z * 18.0 + positionDeformee.y * 6.0 + sin(positionDeformee.y * 10.0) * 0.8) * 0.5 + 0.5);

        vec3 couleurGradationCorps = mix(vec3(0.95, 0.28, 0.03), vec3(0.98, 0.85, 0.1), smoothstep(-0.4, 0.4, positionDeformee.y));
        vec3 couleurCorpsComplete = mix(couleurGradationCorps, vec3(0.92, 0.9, 0.82), motifRayures * smoothstep(-0.1, 0.8, positionDeformee.z));
        vec3 couleurNageoiresComplete = mix(vec3(0.95, 0.18, 0.02), vec3(1.0, 0.65, 0.0), smoothstep(0.0, 0.5, length(positionDeformee.yz)));

        vec3 couleurAlbedoSurface = (distanceYeux < distanceEstimationSurface) ? vec3(0.01) : ((distanceNageoires < distanceCorps) ? couleurNageoiresComplete : couleurCorpsComplete);
        float rugositeSurface = (distanceYeux < distanceEstimationSurface) ? 0.05 : ((distanceNageoires < distanceCorps) ? 0.3 : 0.2);

        if (distanceYeux < distanceEstimationSurface) {
            distanceEstimationSurface = distanceYeux;
        }

        if (distanceEstimationSurface < 0.08) {
            float densiteLocale = smoothstep(0.08, -0.05, distanceEstimationSurface);
            if (densiteLocale > 0.001) {
                vec3 normaleSurface = vec3(0.0);
                vec2 decalageEpsilon = vec2(0.003, 0.0);

                for (int composanteAxe = 0; composanteAxe < 3; composanteAxe++) {
                    vec3 vecteurDecalage = (composanteAxe == 0) ? decalageEpsilon.xyy : ((composanteAxe == 1) ? decalageEpsilon.yxy : decalageEpsilon.yyx);
                    float dTemp1, dTemp2, dTemp3;

                    vec3 posDecalcePositive = appliquerDeformationOndulation(positionCouranteRayon + vecteurDecalage, tempsAnimationPoisson, sin(tempsAnimationPoisson - (positionCouranteRayon + vecteurDecalage).z * 2.2));
                    float distancePositive = calculerCarteDistanceGeometrie(posDecalcePositive, tempsAnimationPoisson, 0.0, dTemp1, dTemp2, dTemp3);

                    vec3 posDecalceNegative = appliquerDeformationOndulation(positionCouranteRayon - vecteurDecalage, tempsAnimationPoisson, sin(tempsAnimationPoisson - (positionCouranteRayon - vecteurDecalage).z * 2.2));
                    float distanceNegative = calculerCarteDistanceGeometrie(posDecalceNegative, tempsAnimationPoisson, 0.0, dTemp1, dTemp2, dTemp3);

                    normaleSurface[composanteAxe] = distancePositive - distanceNegative;
                }
                normaleSurface = normalize(normaleSurface);

                float intensiteOmbrePortee = 1.0;
                float pasOmbre = 0.04;
                vec3 origineOmbre = positionCouranteRayon + normaleSurface * 0.02;

                for (int etapeOmbre = 0; etapeOmbre < 24; etapeOmbre++) {
                    vec3 positionEchantillonOmbre = appliquerDeformationOndulation(origineOmbre + directionLumierePrincipale * pasOmbre, tempsAnimationPoisson, sin(tempsAnimationPoisson - (origineOmbre + directionLumierePrincipale * pasOmbre).z * 2.2));
                    float dTemp1, dTemp2, dTemp3;
                    float distanceOmbre = calculerCarteDistanceGeometrie(positionEchantillonOmbre, tempsAnimationPoisson, sin(tempsAnimationPoisson - positionEchantillonOmbre.z * 2.2), dTemp1, dTemp2, dTemp3);

                    intensiteOmbrePortee = min(intensiteOmbrePortee, 12.0 * distanceOmbre / pasOmbre);
                    pasOmbre += clamp(distanceOmbre, 0.02, 0.2);
                    if (intensiteOmbrePortee < 0.001 || pasOmbre > 2.5) break;
                }
                intensiteOmbrePortee = clamp(intensiteOmbrePortee, 0.0, 1.0);

                float diffusePrincipale = max(dot(normaleSurface, directionLumierePrincipale), 0.0) * intensiteOmbrePortee;
                float diffuseRemplissage = max(dot(normaleSurface, directionLumiereRemplissage), 0.0);
                float diffuseRaseante = pow(clamp(1.0 + dot(directionRayon, normaleSurface), 0.0, 1.0), 3.0) * max(dot(normaleSurface, directionLumiereRaseante), 0.0);

                vec3 demiVecteurReflexion = normalize(directionLumierePrincipale - directionRayon);
                float intensiteSpeculaire = pow(max(dot(normaleSurface, demiVecteurReflexion), 0.0), 1.0 / (rugositeSurface * rugositeSurface)) * intensiteOmbrePortee * 0.8;

                vec3 lumiereDirecteAccumulee = couleurAlbedoSurface * (diffusePrincipale * couleurLumierePrincipale + diffuseRemplissage * couleurLumiereRemplissage) + diffuseRaseante * couleurLumiereRaseante + intensiteSpeculaire;
                vec3 lumiereSubsurface = couleurLumierePrincipale * smoothstep(0.2, -0.2, distanceEstimationSurface) * 0.4 * intensiteOmbrePortee;

                couleurDiffusionVolumetrique += (lumiereDirecteAccumulee + lumiereSubsurface * couleurAlbedoSurface) * densiteLocale * exp(-densiteAccumulee * 8.0) * 0.035;
                densiteAccumulee += densiteLocale * 0.035;

                if (densiteAccumulee > 0.98) break;
            }
        }

        distanceParcourueTotal += max(distanceEstimationSurface * 0.5, 0.035);
        if (distanceParcourueTotal > 6.0) break;
    }

    couleurFinale = couleurArrierePlan * exp(-densiteAccumulee * 8.0) + couleurDiffusionVolumetrique;
    couleurFinale /= (couleurFinale + 1.0);
    couleurFinale = pow(couleurFinale, vec3(1.0 / 2.2));

    float bruitDither = (fract(sin(dot(coordonneeFragment, vec2(12.9898, 78.233))) * 43758.5453) - 0.5) * 0.015;
    couleurFragment = vec4(couleurFinale + bruitDither, 1.0);
}
